Q: How do I establish communication with ELM327 OBDII WiFi device with ESP32 module A: <p>You can do it easily with the right steps:</p>

<ol>
<li>Make sure to setup classic bluetooth with "BluetoothSerial.h"</li>
<li>When calling .begin(), make sure to include the second argument (bool true)</li>
<li>Call .connect("OBDII") to connect to your ELM327</li>
<li>Ensure you only send a carriage return (no newline!) when sending commands/queries to the ELM327</li>
</ol>

<hr>

<p>Here is a simple example program (tested on my own ELM327 today):</p>

<pre><code>#include "BluetoothSerial.h"


BluetoothSerial SerialBT;


#define DEBUG_PORT Serial
#define ELM_PORT   SerialBT


void setup()
{
  pinMode(LED_BUILTIN, OUTPUT);
  digitalWrite(LED_BUILTIN, HIGH);

  DEBUG_PORT.begin(115200);
  ELM_PORT.begin("ESP32test", true);

  DEBUG_PORT.println("Attempting to connect to ELM327...");

  if (!ELM_PORT.connect("OBDII"))
  {
    DEBUG_PORT.println("Couldn't connect to OBD scanner");
    while(1);
  }

  DEBUG_PORT.println("Connected to ELM327");
  DEBUG_PORT.println("Ensure your serial monitor line ending is set to 'Carriage Return'");
  DEBUG_PORT.println("Type and send commands/queries to your ELM327 through the serial monitor");
  DEBUG_PORT.println();
}


void loop()
{
  if(DEBUG_PORT.available())
  {
    char c = DEBUG_PORT.read();

    DEBUG_PORT.write(c);
    ELM_PORT.write(c);
  }

  if(ELM_PORT.available())
  {
    char c = ELM_PORT.read();

    if(c == '&gt;')
      DEBUG_PORT.println();

    DEBUG_PORT.write(c);
  }
}
</code></pre>

<hr>

<p>Also, <a href="https://github.com/PowerBroker2/ELMduino" rel="nofollow noreferrer">ELMduino</a> now supports ESP32 boards for easy connection and vehicle data queries!</p>

Q: ORA-01027: bind variables not allowed for data definition when trying to use if elseif A: <p>As the error says, you can't use bind variables here, so you have to concatenate:</p>

<pre><code>create or replace procedure create_dates_testing 
    ( dummy_variable varchar2 default to_char(sysdate,'YYYYMMDD') )
as
    day_of_month varchar2(255) := extract(day from sysdate);
    today varchar2(255) := to_char(sysdate +1, 'fmDAY', 'nls_date_language = English');
    start_date date;
    next_start_date date;
begin
    if today = 'SUNDAY' then
        -- select yesterday
        start_date      := trunc(sysdate) - interval '1' day;
        next_start_date := trunc(sysdate);

    elsif day_of_month = 3 then
        -- select the whole of last month
        start_date      := trunc(sysdate, 'MM') - interval '1' month;
        next_start_date := trunc(sysdate, 'MM') - interval '1' month;
    else
        return;
    end if;

    execute immediate 'drop table new_customers';

    execute immediate 'create table new_customers as 
    select id, client_name, invoice_date 
    from clients table
    where transactiondate &gt;= date '''  || to_char(start_date,'YYYY-MM-DD') ||
    ''' and transactiondate &lt; date ''' || to_char(next_start_date,'YYYY-MM-DD') ||'''';

end create_dates_testing;
</code></pre>

<p>Presumably there will be some more code to handle the case where it is neither Sunday nor the third of the month, or the <code>new_customers</code> table does not exist.</p>

<p>Edit: added <code>else</code> condition to end processing if neither of the date conditions are met.</p>
